def find_kth(arr1, arr2, k):
    # Ensure arr1 is the smaller array for binary search
    if len(arr1) > len(arr2):
        arr1, arr2 = arr2, arr1

    n1, n2 = len(arr1), len(arr2)
    low, high = max(0, k - n2), min(n1, k - 1)

    while low <= high:
        cut1 = (low + high) // 2
        cut2 = k - cut1

        left1 = arr1[cut1 - 1] if cut1 > 0 else -math.inf
        left2 = arr2[cut2 - 1] if cut2 > 0 else -math.inf
        right1 = arr1[cut1] if cut1 < n1 else math.inf
        right2 = arr2[cut2] if cut2 < n2 else math.inf

